INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 36, 'theory', 'Quiz: regular expressions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 0, 'What does the pattern r"\d{3}" mean?', '["Exactly three digits in a row", "The digit 3", "From zero to three digits", "Any three characters"]', 0, '\d is a digit, {3} is exactly three repetitions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 1, 'How does re.match differ from re.search?', '["It does not", "match checks only the start of the string, search looks anywhere", "search is faster", "match finds all matches"]', 1, 'To search anywhere you need search; match is anchored to the start.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 2, 'What will re.search(r"<.*>", "<a><b>").group() return?', '["<a>", "<a><b>", "<b>", "None"]', 1, 'The * quantifier is greedy and takes the maximum; for the minimum you need .*?');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 3, 'Why are patterns written as raw strings r"..."?', '["It is faster", "So that Python does not process backslashes", "So that Russian letters work", "The re module requires it"]', 1, 'Without the r prefix, "\d" would have to be written as "\\d".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 4, 'What must you do before calling m.group(1), if m = re.search(...)?', '["Nothing", "Check that m is not None: if there is no match, search returns None", "Call re.compile", "Convert it to a list"]', 1, 'If there is no match, m is None, and calling a method on it fails with AttributeError.');
